-- MiniMax Week hackathon feature: per-artwork theme songs generated by
-- MiniMax Music 3.0 (lyrics reasoned by MiniMax M3). One song per
-- artwork + locale, reused across visitors to avoid regenerating the ~2min job.
--
-- Namespaced with the `mm_` prefix so the campaign feature stays fully
-- separated from the original schema (artwork_guides / guide_feedback) even
-- though it lives in the same database. Artwork catalog/guide data is shared
-- with the main app; only the generated song + lyrics are stored here.

CREATE TABLE IF NOT EXISTS mm_theme_songs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  slug TEXT NOT NULL,
  locale TEXT NOT NULL DEFAULT 'ja',
  audio_url TEXT NOT NULL,
  lyrics TEXT NOT NULL DEFAULT '',
  style_prompt TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (slug, locale)
);

CREATE INDEX IF NOT EXISTS mm_theme_songs_slug_idx ON mm_theme_songs (slug, locale);
